CodeInjections.CodeInjection:
{
    // 3a. pozycja suwaka + automatyczne przewijanie w czasie
    //     (odpowiednik frac(object.sliderPos.y * cTime_s) z FS25)
    float mSliderOffset  = sliderPos.y * time.y;
    mSliderOffset       -= floor(mSliderOffset);            // = frac()

    Out.mSliderThreshold = sliderPos.x + mSliderOffset;

    // 3b. wspolrzedna wzdluz paska swiecenia.
    //     FS13 nie ma drugiego zestawu UV (uv1), dlatego uzywamy
    //     wspolrzednej X podstawowego UV mesha (0..1 wzdluz paska).
    float2 mSliderUV = getTexCoords(In, ALBEDOMAP_TEXCOORD);
    Out.mSliderCoord = mSliderUV.x;
}

// Nazwy interpolantow z VS_OUTPUT.
// Jesli Twoja wersja silnika FS13 nazywa strukture inaczej (np. In.mSliderCoord),
// wystarczy podmienic te dwie linie - patrz sekcja "Rozwiazywanie problemow" w README.
#define GS_SLIDER_COORD     In.vs.mSliderCoord
#define GS_SLIDER_THRESHOLD In.vs.mSliderThreshold

{
    // twarda maska 0/1 - dokladnie jak warunek "<= sliderPos.x + frac(...)" w FS25
    float mSliderMask = (GS_SLIDER_COORD <= GS_SLIDER_THRESHOLD) ? 1.0 : 0.0;

    // ------------------------------------------------------------------
    // WARIANT ZAPASOWY - tylko jesli silnik FS13 nie obsluguje VS_OUTPUT.
    // Wtedy: usun blok VS_OUTPUT oraz blok POST_SET_TEXCOORDS_VS z tego pliku,
    // a linijke z mSliderMask powyzej zastap trzema liniami ponizej:
    //
    //   float2 mSliderUV  = getTexCoords(In, ALBEDOMAP_TEXCOORD);
    //   float  mThreshold = sliderPos.x + frac(sliderPos.y * time.y);
    //   float  mSliderMask = (mSliderUV.x <= mThreshold) ? 1.0 : 0.0;
    // ------------------------------------------------------------------

    // 1.0 = normalne swiecenie, 0.0 = zgaszone
    float mGlowScale  = saturate(lightControl.x);

    oColor.rgb *= mSliderMask * mGlowScale;

#ifdef ALPHA_BLENDED
    // w materialach z alphaBlending czesc "zgaszona" musi byc w pelni przezroczysta
    oColor.a *= mSliderMask;
#endif
}
